import { app, page, route, query, action, api, apiNamespace } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { FolderPage } from "./src/FolderPage" with { type: "ref" };
import { LogsPage } from "./src/LogsPage" with { type: "ref" };
import { SharePage } from "./src/SharePage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };

import { getFolderContent, getAccessLogs, getShareLink } from "./src/queries" with { type: "ref" };
import { createFolder, createShareLink, uploadFileMetadata } from "./src/actions" with { type: "ref" };
import { configureFileUploadMiddleware, uploadFile, downloadFile } from "./src/apis" with { type: "ref" };

export default app({
  name: "app",
  wasp: { version: "^0.25.0" },
  title: "Wasp File Manager",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  spec: [
    route("SignupRoute", "/signup", page(SignupPage)),
    route("LoginRoute", "/login", page(LoginPage)),
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("FolderRoute", "/folder/:folderId", page(FolderPage, { authRequired: true })),
    route("LogsRoute", "/logs", page(LogsPage, { authRequired: true })),
    route("ShareRoute", "/share/:linkId", page(SharePage)),

    query(getFolderContent, { entities: ["Folder", "File"] }),
    query(getAccessLogs, { entities: ["AccessLog", "ShareLink", "File"] }),
    query(getShareLink, { entities: ["ShareLink", "File"] }),

    action(createFolder, { entities: ["Folder"] }),
    action(createShareLink, { entities: ["ShareLink", "File"] }),
    action(uploadFileMetadata, { entities: ["File"] }),

    apiNamespace("/api/upload", { middlewareConfigFn: configureFileUploadMiddleware }),
    api("POST", "/api/upload", uploadFile, { entities: ["File"], auth: true }),
    api("GET", "/api/download/:linkId", downloadFile, { entities: ["ShareLink", "AccessLog", "File"], auth: false }),
  ],
});

import { type GetFolderContent, type GetAccessLogs, type GetShareLink } from "wasp/server/operations";

export const getFolderContent: GetFolderContent<
  { folderId: number | null },
  {
    folders: any[];
    files: any[];
    breadcrumbs: any[];
  }
> = async (args, context) => {
  if (!context.user) {
    throw new Error("Unauthorized");
  }

  const userId = context.user.id;
  const folderId = args.folderId;

  // Fetch folders and files in this folder (or root)
  const folders = await context.entities.Folder.findMany({
    where: {
      userId,
      parentId: folderId,
    },
    orderBy: {
      name: "asc",
    },
  });

  const files = await context.entities.File.findMany({
    where: {
      userId,
      folderId,
    },
    include: {
      shareLinks: {
        orderBy: {
          createdAt: "desc",
        },
        take: 1,
      },
    },
    orderBy: {
      name: "asc",
    },
  });

  // Construct breadcrumbs if folderId is provided
  let breadcrumbs: any[] = [];
  if (folderId) {
    let currentFolder = await context.entities.Folder.findFirst({
      where: { id: folderId, userId },
    });

    while (currentFolder) {
      breadcrumbs.unshift({
        id: currentFolder.id,
        name: currentFolder.name,
      });

      if (currentFolder.parentId) {
        currentFolder = await context.entities.Folder.findFirst({
          where: { id: currentFolder.parentId, userId },
        });
      } else {
        currentFolder = null;
      }
    }
  }

  return {
    folders,
    files,
    breadcrumbs,
  };
};

export const getAccessLogs: GetAccessLogs<void, any[]> = async (args, context) => {
  if (!context.user) {
    throw new Error("Unauthorized");
  }

  // Fetch access logs for files owned by the logged-in user
  const logs = await context.entities.AccessLog.findMany({
    where: {
      shareLink: {
        file: {
          userId: context.user.id,
        },
      },
    },
    include: {
      shareLink: {
        include: {
          file: true,
        },
      },
    },
    orderBy: {
      timestamp: "desc",
    },
  });

  return logs.map((log) => ({
    id: log.id,
    timestamp: log.timestamp,
    ipAddress: log.ipAddress,
    userAgent: log.userAgent,
    fileName: log.shareLink.file.name,
  }));
};

export const getShareLink: GetShareLink<
  { linkId: string; password?: string },
  {
    id: string;
    hasPassword: boolean;
    passwordCorrect: boolean;
    fileName?: string;
    fileSize?: number;
    expired: boolean;
    notFound?: boolean;
  }
> = async (args, context) => {
  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: args.linkId },
    include: {
      file: true,
    },
  });

  if (!shareLink) {
    return {
      id: args.linkId,
      hasPassword: false,
      passwordCorrect: false,
      expired: false,
      notFound: true,
    };
  }

  const isExpired = shareLink.expiresAt && new Date() > shareLink.expiresAt;

  if (isExpired) {
    return {
      id: shareLink.id,
      hasPassword: !!shareLink.password,
      passwordCorrect: false,
      expired: true,
    };
  }

  const hasPassword = !!shareLink.password;
  let passwordCorrect = !hasPassword;

  if (hasPassword && args.password) {
    passwordCorrect = shareLink.password === args.password;
  }

  return {
    id: shareLink.id,
    hasPassword,
    passwordCorrect,
    fileName: shareLink.file.name,
    fileSize: shareLink.file.size,
    expired: false,
  };
};

import { type CreateFolder, type CreateShareLink, type UploadFileMetadata } from "wasp/server/operations";

const runId = "zrula60lhl";

export const createFolder: CreateFolder<{ name: string; parentId: number | null }, any> = async (args, context) => {
  if (!context.user) {
    throw new Error("Unauthorized");
  }

  let folderName = args.name;
  if (!folderName.endsWith(`-${runId}`)) {
    folderName = `${folderName}-${runId}`;
  }

  const newFolder = await context.entities.Folder.create({
    data: {
      name: folderName,
      parentId: args.parentId,
      userId: context.user.id,
    },
  });

  return newFolder;
};

export const createShareLink: CreateShareLink<
  { fileId: number; password?: string; expiresMinutes?: number },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new Error("Unauthorized");
  }

  const file = await context.entities.File.findFirst({
    where: {
      id: args.fileId,
      userId: context.user.id,
    },
  });

  if (!file) {
    throw new Error("File not found or access denied");
  }

  let expiresAt: Date | null = null;
  if (args.expiresMinutes && args.expiresMinutes > 0) {
    expiresAt = new Date(Date.now() + args.expiresMinutes * 60 * 1000);
  }

  const shareLink = await context.entities.ShareLink.create({
    data: {
      password: args.password || null,
      expiresAt,
      fileId: args.fileId,
    },
  });

  return shareLink;
};

